"""Evidence audit + transparent source limits; never manufactures missing flags."""
import sys,json,shutil,hashlib,xml.etree.ElementTree as ET
from pathlib import Path
sys.path.insert(0,str(Path(__file__).resolve().parents[1]))
import pandas as pd
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
from src.common import ROOT,save_json
from src.history_sources import HISTORY,ATTRIBUTION
out=ROOT/'outputs/history_evidence';out.mkdir(parents=True,exist_ok=True);fig=out/'figures';fig.mkdir(exist_ok=True)
folder=HISTORY/'processed';evidence=json.loads((folder/'evidence_summary.json').read_text());f=pd.read_parquet(folder/'station_status_points.parquet');hour=pd.read_parquet(folder/'operating_hour_evidence.parquet');panel=pd.read_parquet(ROOT/'data/processed/panel.parquet');unknown=panel[panel.active_flag==0][['station_id','hour']]
x=unknown.merge(hour,on=['station_id','hour'],how='left',validate='one_to_one')
x['evidence_class']=np.select([x.sample_supported_active_hour.eq(True),x.all_observed_flags_active.eq(True),x.observations.notna()],['all_12_5min_bins_active','some_active_points_only','at_least_one_restricted_point'],default='no_fresh_consistent_point')
x.to_csv(out/'unknown_hour_evidence.csv.gz',index=False)
counts=x.evidence_class.value_counts().rename_axis('evidence_class').reset_index(name='station_hours');counts.to_csv(out/'unknown_hour_summary.csv',index=False)
assert counts.station_hours.sum()==19634
# Keep unknown labels unless the explicitly declared 12-bin sampling criterion holds.
enriched=panel.merge(hour[['station_id','hour','observations','covered_5min_bins','sample_supported_active_hour','observed_disabled']],on=['station_id','hour'],how='left',validate='one_to_one')
recovered=enriched.active_flag.eq(0)&enriched.sample_supported_active_hour.eq(True)
enriched.loc[recovered,['departures','arrivals','netflow']]=0;enriched.loc[recovered,'active_flag']=1;enriched.loc[recovered,'activity_source']='archived_GBFS_12_of_12_bins_sample_support_not_continuous_proof'
enriched.to_parquet(folder/'panel_with_evidence.parquet',index=False)
x[x.evidence_class!='all_12_5min_bins_active'][['station_id','hour','evidence_class']].to_csv(out/'remaining_hours_for_data_request.csv.gz',index=False)
# Corroborate CityBikes capacity against dated official archives; only use preceding points.
cap=pd.read_csv(folder/'official_capacity_points.csv',dtype={'station_id':str});cap['observed_at']=pd.to_datetime(cap.observed_at,utc=True).astype('datetime64[ns, UTC]');cap=cap.rename(columns={'capacity':'official_reported_capacity'})
good=f[f.fresh & f.valid_counts].copy();good['timestamp']=good.timestamp.astype('datetime64[ns, UTC]');good=good[['station_id','timestamp','capacity']].rename(columns={'capacity':'citybikes_reported_capacity'})
joined=pd.merge_asof(cap.sort_values('observed_at'),good.sort_values('timestamp'),left_on='observed_at',right_on='timestamp',by='station_id',direction='backward',tolerance=pd.Timedelta(hours=1))
joined['equal_when_matched']=joined.official_reported_capacity==joined.citybikes_reported_capacity;joined.to_csv(out/'capacity_corroboration.csv',index=False)
# Event-sampled statistics, not time-weighted operational failure rates.
valid=f[f.valid_counts & f.fresh].copy();stats=valid.groupby('station_id').agg(valid_points=('bikes','size'),capacity_min=('capacity','min'),capacity_max=('capacity','max'),zero_bike_points=('bikes',lambda s:int((s==0).sum())),zero_dock_points=('free',lambda s:int((s==0).sum())))
stats.to_csv(out/'valid_station_evidence.csv')
plt.figure(figsize=(11,4));pos=np.arange(len(stats));plt.vlines(pos,stats.capacity_min,stats.capacity_max);plt.scatter(pos,stats.capacity_min,label='min report');plt.scatter(pos,stats.capacity_max,label='max report');plt.axhline(25,c='red',ls='--',label='original assumed 25');plt.xticks(pos,stats.index,rotation=90,fontsize=7);plt.ylabel('Reported slots in internally consistent samples');plt.legend();plt.title('Historical reported capacity varies; no interpolation across missing updates');plt.tight_layout();plt.savefig(fig/'historical_capacity.png',dpi=140);plt.close()
counts.set_index('evidence_class').station_hours.plot.bar(figsize=(9,4));plt.ylabel('Previously operating-unknown station-hours');plt.title('Evidence strength: point support is not continuous operation proof');plt.tight_layout();plt.savefig(fig/'operating_evidence_gaps.png',dpi=140);plt.close()
cal=pd.read_csv(ROOT/'outputs/history_calibrated/simulation_summary.csv');weather=pd.read_csv(ROOT/'outputs/weather/weather_ablation_uncertainty.csv');stochastic=pd.read_csv(ROOT/'outputs/stochastic/summary.csv');routes=pd.read_csv(ROOT/'outputs/routing/routing_hours.csv');dur=pd.read_csv(ROOT/'outputs/duration_sensitivity/forecast_metrics.csv');network=pd.read_csv(ROOT/'outputs/network60/simulation_summary.csv')
route_counts=routes.groupby(['strategy','status']).size().rename('hours').reset_index();route_counts.to_csv(out/'route_status_summary.csv',index=False)
test_root=ET.parse(ROOT/'reports/validation/pytest.xml').getroot()
test_suites=list(test_root.findall('testsuite')) if test_root.tag=='testsuites' else [test_root]
tests_passed=sum(int(s.attrib.get('tests',0))-int(s.attrib.get('failures',0))-int(s.attrib.get('errors',0))-int(s.attrib.get('skipped',0)) for s in test_suites)
record=evidence|dict(invalid_count_points=int((~f.valid_counts).sum()),valid_fresh_points=len(valid),official_capacity_points=len(cap),capacity_corroboration_matches=int(joined.citybikes_reported_capacity.notna().sum()),capacity_corroboration_equal=int(joined.equal_when_matched.sum()),calibrated_common_hours=int(cal.hours.iloc[0]),weather_lead_hours=24,duration_thresholds=sorted(dur.cutoff_minutes.unique().tolist()),stochastic_horizon=3,stochastic_scenarios=4,stochastic_hours=48,network_sites=60,network_hours=336,pytest_passed=tests_passed)
save_json(out/'completion_evidence.json',record)
rows=[f'''# 历史证据与扩展研究：最终核对\n\n## 已找到并接入的历史数据\n\n- CityBikes 2025 年纽约 12 个月历史 Parquet，匹配全部 30 个研究站点，{len(f):,} 条历史状态变化记录。包含可借车辆、空桩、报告容量、租还车标记及源时间戳。\n- 2025 年官方 GBFS 的互联网存档：4 份 station_information、6 份 station_status；所选站点得到 {len(cap)} 条容量点证据和 {evidence['official_status_points']} 条库存/营业标记点证据。使用官方 short_name → UID 映射并核对坐标，不凭站名猜测。\n- {record['invalid_count_points']:,} 条记录出现车辆/空桩与报告容量不一致，明确排除出有效校准样本。真实源数据也需要审计，不能直接把字段当无误的物理真值。\n- CityBikes 容量与之前一小时内可匹配的官方容量点对照：{record['capacity_corroboration_equal']}/{record['capacity_corroboration_matches']} 相等；未匹配和不等的记录全部保留。不同时间的近邻比对不是同时刻完全一致性的保证。\n\n## 哪些运营缺口能恢复\n\n```csv\n{counts.to_csv(index=False)}```\n\n原 19,634 个未知小时中，{evidence['previous_unknown_point_supported']:,} 个有新鲜、内部一致且未观测到限制的营业点记录；其中只有 {evidence['previous_unknown_recovered']} 个满足已声明的全部 12 个五分钟箱采样支持条件。单个营业点不能证明整个小时一直营业；强采样支持也不是连续每秒在线的证明。剩余 {evidence['previous_unknown_remaining']:,} 个小时仍不满足这一强标准，保留未知，未伪造零需求。\n\n根本原因是归档只记录 (bikes, free) 变化，数量不变时会过滤记录，可能遗漏只改变营业标记的更新。2025 年初和年末的归档代码版本均可追溯；服务实际部署连续性仍不可独立证明。故“没有新记录”不能被解释为停运或连续正常营业，也不能可靠估计时间加权空站/满站时长。归档以 UTC 月份组织，与 NYC 本地年尾还存在边界覆盖区别。\n\n纽约开放数据 Bike Share Inspections (Historical) 实际日期范围为 2013-05-28 至 2020-03-13，不能证明 2025 状态。市审计长有关可靠性的报告使用 2023 年 6–7 月数据，亦不能冒充 2025。\n\n## 使用历史实测状态的新实验\n\n仅使用决策前且报告年龄不超过 15 分钟、容量一致、租还车启用的共同状态。质量筛查后有 {record['calibrated_common_hours']} 个测试小时同时覆盖全部 30 站。每个小时三策略从相同实测库存重置，使用实测 bikes+free 作为当时可用容量；报告物理 slots 另列。不是连续两个月的真实车队反事实。\n\n```csv\n{cal.to_csv(index=False)}```\n\n这组状态重置、时间子集与旧的 25 容量全测试期压力场景不同，不能直接比较两表服务率来声称现实改善。采样偏向有数量变化和繁忙时段，仍有选择偏差。\n\n## 新增实验均已实际运行\n\n1. **天气消融**：使用 Open-Meteo Previous Runs 的 GFS 24 小时前预报，不使用目标小时实测/再分析。固定原 XGBoost 参数，保持同样目标和随机样本。\n\n```csv\n{weather.to_csv(index=False)}```\n\n2. **时长清洗敏感性**：从全部原始 ZIP 重读，比较 30/60/90/120/180/360 分钟；180 分钟结果与原始端点总量及预测指标完全重合。每个阈值固定模型架构、重拟合，并比较同条件策略。阈值改变目标记录集合，误差不能简单跨阈值排名。\n\n```csv\n{dur.to_csv(index=False)}```\n\n3. **随机多期优化**：三小时 MPC、四个相关场景，噪声来自验证期联合残差块。未来多步特征递归生成，未知未来真实值被清空；每轮只执行第一步。共享整数搬运，场景库存连续近似，末端安全区间半权重；请求求解 gap=2%，求解状态与回退明确。测试为 48 小时共同事件路径。\n\n```csv\n{stochastic.to_csv(index=False)}```\n\n4. **卡车路径**：两车、每车 6 辆、15 km/h、60 分钟班次、每辆每次装/卸 1.5 分钟；对前 48 小时的 Greedy/MILP 订单做原子取送路径 MILP。禁止共同装载多任务，属于受限取送路径模型，不是一般 VRP 或实际路网调度系统。\n\n```csv\n{route_counts.to_csv(index=False)}```\n\n不可行是这些固定订单在所选受限模型下不能全部完成，不是一般运输问题不可行的证明。没有把失败订单当成功，也没有把瞬时仿真服务收益说成可实际调度执行的收益。\n\n5. **网络扩展**：60 个仅训练期筛选的站点，525,600 panel 行，87,900 测试站点小时，三策略各 336 小时。用官方 26c 行政区多边形（水域包含）作明确分析边界，原 30 站均在内；这不是 2025 库存证据，也不冒充历史版区界。固定每小时预算 12，属于规模和资源压力研究，不能与 30 站不同需求范围当作同样本因果比较。\n\n```csv\n{network.to_csv(index=False)}```\n\n上述新增分析发生在原测试已查看之后，均如实标为探索性扩展；未宣称有新的未触碰测试集。\n\n## 来源与复现\n\n- https://data.citybik.es/ （2025 分网络档案；ODbL-1.0）\n- https://web.archive.org/cdx/search/cdx （官方 GBFS 的 2025 捕获索引与原始 JSON）\n- https://github.com/citybikes/analytics/blob/353535785bd70f61e8ef3cadc26ff64211eba95c/collect.py （2025 年初源码）\n- https://github.com/citybikes/analytics/blob/5cd7338c9e1502a194857d4956f594a16aecabc3/collect.py （2025 年末源码）\n- https://data.cityofnewyork.us/resource/5uei-swth.json （检查记录覆盖范围已实查）\n- https://open-meteo.com/en/docs/previous-runs-api （提前 24 小时预报定义）\n\n{ATTRIBUTION}\nCityBikes contributors. (2026) Bike-share data retrieved from https://data.citybik.es .\n\nCityBikes 衍生数据库按 ODbL-1.0 提供，原运营方数据条款仍适用；天气数据注明 Open-Meteo/NOAA 来源。下载清单、原始快照、SHA256、处理程序和所有结果均保留。已有 {record['pytest_passed']} 项测试通过，包括未来信息隔离、历史时间与新鲜度、异常容量拒绝、随机规划穷举检验、路径容量/工时/不可行状态等。\n\n## 仍需外部原始记录的部分\n\n要彻底消除剩余运营证据缺口，需要运营方/归档方提供包含“数量不变”和“仅标记改变”更新的连续原始 GBFS 心跳或维护日志。已准备精确字段与时间范围的数据请求草稿，但未擅自向任何人发送。新的公共证据显著增加了可验证范围，不能因此把未观测状态伪造成事实。即使未来拿到完整库存，也仍不能从库存反推出所有潜在被拒请求数。\n''']
(ROOT/'reports/historical_evidence_and_extensions.md').write_text('\n'.join(rows))
